const PERIODS = [
  {k:'today', l:'Today', vs:'yesterday', n:12, unit:'h'},
  {k:'week', l:'This week', vs:'last week', n:7, unit:'d'},
  {k:'lastweek', l:'Last week', vs:'the week before', n:7, unit:'d'},
  {k:'month', l:'Monthly', vs:'last month', n:30, unit:'md'},
  {k:'quarter', l:'Quarterly', vs:'last quarter', n:13, unit:'w'},
  {k:'year', l:'Yearly', vs:'last year', n:12, unit:'m'}
];
const rangeLabel = P => {
  const f = (d, o) => d.toLocaleDateString('en-US', o);
  const d = new Date(NOW);
  if (P.k === 'today') return f(d, {weekday:'long', month:'long', day:'numeric'});
  if (P.k === 'week' || P.k === 'lastweek'){ const s = new Date(d); s.setDate(d.getDate() - ((d.getDay() + 6) % 7) - (P.k === 'lastweek' ? 7 : 0)); const e = new Date(s); e.setDate(s.getDate() + 6); return `${f(s, {month:'short', day:'numeric'})} to ${f(e, {month:'short', day:'numeric'})}`; }
  if (P.k === 'month') return f(d, {month:'long', year:'numeric'});
  if (P.k === 'quarter') return `Q${Math.floor(d.getMonth() / 3) + 1} ${d.getFullYear()}`;
  return String(d.getFullYear());
};
/* the x-axis labels and which slot is "now" */
const axis = P => {
  const d = new Date(NOW);
  if (P.unit === 'h') return {lbl: Array.from({length:12}, (_, i) => { const h = 9 + i; return `${((h + 11) % 12) + 1}${h < 12 ? 'a' : 'p'}`; }), cur: Math.min(11, Math.max(0, d.getHours() - 9))};
  if (P.unit === 'd') return {lbl: ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], cur: P.k === 'week' ? (d.getDay() + 6) % 7 : 7};
  if (P.unit === 'md') return {lbl: Array.from({length:30}, (_, i) => String(i + 1)), cur: Math.min(29, d.getDate() - 1)};
  if (P.unit === 'w') return {lbl: Array.from({length:13}, (_, i) => 'W' + (i + 1)), cur: Math.min(12, Math.floor((d.getMonth() % 3) * 4.33 + d.getDate() / 7))};
  return {lbl: ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], cur: d.getMonth()};
};
const SCALE = {today:1, week:7, lastweek:7, month:30, quarter:91, year:365};
const metrics = P => {
  const r = rng(hash(P.k)), s = SCALE[P.k];
  const ax = axis(P);
  const per = P.unit === 'h' ? 4 : P.unit === 'd' ? 26 : P.unit === 'md' ? 24 : P.unit === 'w' ? 170 : 720;
  const series = ax.lbl.map((_, i) => {
    const weekend = P.unit === 'd' && i >= 5 ? 1.35 : 1;
    const v = Math.round(per * weekend * (0.55 + r() * 0.9));
    const pv = Math.round(per * weekend * (0.5 + r() * 0.8));
    return {v: i > ax.cur ? 0 : v, p: pv, fut: i > ax.cur};
  });
  const searches = series.reduce((a, b) => a + b.v, 0);
  const prevSearches = Math.round(series.reduce((a, b) => a + b.p, 0) * (P.k === 'week' || P.k === 'today' || P.k === 'month' || P.k === 'quarter' || P.k === 'year' ? (ax.cur + 1) / series.length : 1));
  const soldCount = Math.max(P.k === 'today' ? 0 : 1, Math.round(s / 9 * (0.6 + r() * 0.8)) + (P.k === 'week' ? 1 : 0));
  let prevSold = Math.max(1, Math.round(s / 9 * (0.6 + r() * 0.8)));
  const avgPrice = 300000 + r() * 90000;
  const pendCount = 2 + Math.round(r() * Math.min(6, s / 20));
  return {series, ax, searches, prevSearches, soldCount, prevSold, soldValue: soldCount * avgPrice, pendCount, pendValue: pendCount * (320000 + r() * 80000), r};
};
const pct = (a, b) => b ? Math.round((a - b) / b * 100) : 0;

