/* ================= Photo slots: four photos, JPEG or PNG, 5 MB each (US-04) ================= */
const MAXMB = 5;
const readPhoto = file => new Promise((res, rej) => {
  if (!/^image\/(jpeg|png)$/.test(file.type)) return rej(`${file.name} is not a JPEG or PNG.`);
  if (file.size > MAXMB * 1048576) return rej(`${file.name} is ${(file.size / 1048576).toFixed(1)} MB. The limit is ${MAXMB} MB.`);
  const fr = new FileReader();
  fr.onerror = () => rej(`${file.name} could not be read.`);
  fr.onload = () => { const img = new Image(); img.onload = () => {
    /* shrink to 960 px wide so pages stay quick on phones and the disk quota holds */
    const s = Math.min(1, 960 / img.width), c = document.createElement('canvas'); c.width = Math.round(img.width * s); c.height = Math.round(img.height * s);
    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
    let src; try{ src = c.toDataURL('image/jpeg', .74); }catch(e){ src = fr.result; }
    res({src, name:file.name, w:img.width, h:img.height});
  }; img.onerror = () => rej(`${file.name} could not be opened as an image.`); img.src = fr.result; };
  fr.readAsDataURL(file);
});
function photoSlots(box, start, onChange){
  const P = [0, 1, 2, 3].map(i => start && start[i] ? {...start[i]} : null);
  const paint = () => {
    const n = P.filter(Boolean).length;
    box.innerHTML = `<div class="ph-grid">${P.map((p, i) => p ? `<div class="ph-slot on" data-i="${i}" draggable="true">
        <div class="ph-img">${p.src ? `<img src="${p.src}" alt="">` : p.art}<span class="ph-n">${i === 0 ? 'Cover' : 'Photo ' + (i + 1)}</span>
          <div class="ph-acts"><button type="button" class="rbtn sm" data-mv="-1" aria-label="Move photo ${i + 1} earlier"${i === 0 ? ' disabled' : ''}>${ico('chevR', 'rev')}</button><button type="button" class="rbtn sm" data-mv="1" aria-label="Move photo ${i + 1} later"${i === 3 ? ' disabled' : ''}>${ico('chevR')}</button><button type="button" class="rbtn sm" data-rm aria-label="Remove photo ${i + 1}">${ico('trash')}</button></div></div>
        <div class="fld ph-alt"><label class="sr" for="alt${i}">Description of photo ${i + 1}</label><input id="alt${i}" data-alt="${i}" value="${esc(p.alt)}" maxlength="150" placeholder="What the photo shows"></div></div>`
      : `<label class="ph-slot empty" data-i="${i}"><input type="file" accept="image/jpeg,image/png" class="sr" data-file="${i}"><span class="ph-drop">${ico('upload')}<b>${i === 0 ? 'Add the cover photo' : 'Add photo ' + (i + 1)}</b><small>JPEG or PNG, up to ${MAXMB} MB</small></span></label>`).join('')}</div>
      <div class="ph-bar"><span class="ph-cnt${n === 4 ? ' ok' : ''}">${ico(n === 4 ? 'check' : 'image')}${n} of 4 photos</span><label class="pbtn ghost sm ph-multi">${ico('upload')}Choose several<input type="file" accept="image/jpeg,image/png" multiple class="sr" data-multi></label><small class="muted">Drag photos to reorder. The first one is the cover.</small></div>`;
    onChange(P);
  };
  const place = async (files, at) => {
    const errs = [];
    for (const f of files){
      let i = at != null && !P[at] ? at : P.findIndex(p => !p);
      if (i < 0){ errs.push('A listing has exactly four photos. Remove one to add another.'); break; }
      try{ const r = await readPhoto(f); P[i] = {src:r.src, alt: PHOTO_LBL[i]}; }catch(m){ errs.push(m); }
      at = null;
    }
    paint();
    if (errs.length) toast(errs[0]);
  };
  box.addEventListener('change', e => { const t = e.target; if (t.dataset.file != null) place([...t.files], +t.dataset.file); if (t.dataset.multi != null) place([...t.files]); });
  box.addEventListener('input', e => { const t = e.target; if (t.dataset.alt != null){ const p = P[+t.dataset.alt]; p.alt = t.value; delete p.keep; onChange(P); } });
  box.addEventListener('click', e => {
    const s = e.target.closest('.ph-slot'); if (!s) return; const i = +s.dataset.i;
    const mv = e.target.closest('[data-mv]'); if (mv){ const j = i + +mv.dataset.mv; [P[i], P[j]] = [P[j], P[i]]; paint(); $(`.ph-slot[data-i="${j}"] [data-mv="${mv.dataset.mv}"]`, box)?.focus(); return; }
    if (e.target.closest('[data-rm]')){ P[i] = null; paint(); }
  });
  let dragI = null;
  box.addEventListener('dragstart', e => { const s = e.target.closest('.ph-slot.on'); if (!s) return; dragI = +s.dataset.i; e.dataTransfer.effectAllowed = 'move'; s.classList.add('dragging'); });
  box.addEventListener('dragend', () => { dragI = null; $$('.ph-slot', box).forEach(s => s.classList.remove('dragging', 'over')); });
  box.addEventListener('dragover', e => { const s = e.target.closest('.ph-slot'); if (!s) return; e.preventDefault(); $$('.ph-slot', box).forEach(x => x.classList.toggle('over', x === s)); });
  box.addEventListener('dragleave', e => { const s = e.target.closest('.ph-slot'); if (s && !s.contains(e.relatedTarget)) s.classList.remove('over'); });
  box.addEventListener('drop', e => { const s = e.target.closest('.ph-slot'); if (!s) return; e.preventDefault(); const j = +s.dataset.i;
    if (e.dataTransfer.files && e.dataTransfer.files.length){ place([...e.dataTransfer.files], j); return; }
    if (dragI != null && dragI !== j){ [P[dragI], P[j]] = [P[j], P[dragI]]; paint(); } });
  paint();
  return P;
}

/* ================= Add or edit a listing (US-03, US-04) ================= */
