      options: FEAT_SUGGEST.map(f => ({value:f, text:f})), render:{option_create: (d, e) => `<div class="create">Add <b>${e(d.input)}</b></div>`, no_results: () => '<div class="no-results">Type a feature and press Enter</div>'},
      onItemAdd(){ this.setTextboxValue(''); this.refreshOptions(false); },
