  $$('.t-sel select', f).forEach(enhanceSelect);
  let photos = [], dirty = false;
  const startPhotos = X ? [0, 1, 2, 3].map(i => X.photos ? X.photos[i] : {art: houseThumb(X.id * 4 + i), alt: PHOTO_LBL[i], keep:true}) : null;
