    const n = photos.filter(Boolean).length, altMissing = photos.some(p => p && !p.alt.trim());
    if (n !== 4 || altMissing){ const msg = n !== 4 ? `${n} of 4 photos added. A listing needs exactly four.` : 'Describe each photo in a few words. Screen readers read these out.'; $('#phFld').classList.add('err'); $('#phErr').innerHTML = ico('alert') + msg; errs.push([$('#phBox'), msg]); }
