const notFound = () => `<section class="card nf"><span class="nf-ic">${ico('search')}</span><h2>We couldn't find that listing</h2><p>It may have been opened from an old link. Hidden listings are still kept, so check the Hidden tab.</p><div class="nf-a"><a class="pbtn acc" href="admin-listings.html">Go to All listings</a><a class="pbtn ghost" href="admin-listings.html?tab=hidden">Open the Hidden tab</a></div></section>`;

